<?php
declare(strict_types=1);
function seedDemo():void{
 $t='DEMONSTRACAO';if(one('SELECT id FROM tr_tenants WHERE id=?',[$t]))throw new Fault('A base DEMONSTRAÇÃO já existe; a importação não será repetida.');$base=json_decode((string)file_get_contents(TR_RELEASE.'/data/base.json'),true);query('INSERT INTO tr_tenants(id,name,state,is_demo) VALUES(?,?,?,1)',[$t,'DEMONSTRAÇÃO','DEMO']);
 $units=[];foreach($base['people'] as $p)if(!isset($units[$p['unit']])){$id='UNIT-'.substr(hash('sha256',$p['unit']),0,20);$units[$p['unit']]=$id;save($t,'units',['id'=>$id,'name'=>$p['unit'],'power'=>$p['power']]);}
 foreach($base['plans'] as $p){$categories=[['id'=>'demo-capacitacao','label'=>$p['family']==='magisterio'?'Formação continuada em educação':'Capacitação pertinente ao cargo','destination'=>'Progressão horizontal','kind'=>'Capacitação','minHours'=>8,'basis'=>$p['act'],'requirements'=>'Conferir documento, período, pertinência e aprovação unânime. Horas por ciclo: '.($p['family']==='legislativo'?30:40).'.'],['id'=>'demo-titulacao','label'=>'Nova titulação / formação pertinente ao cargo','destination'=>'Promoção vertical','kind'=>'Titulação','minHours'=>0,'basis'=>$p['act'],'requirements'=>'Diploma, histórico e requisitos do cargo. Especialização: mínimo 360 horas. O nível de destino exige conferência da comissão.']];$p['basis']=$p['act'];$p['certificateCategories']=$categories;save($t,'plans',$p);$frame=save($t,'salary_frames',['id'=>'FRAME-'.$p['id'],'name'=>$p['name'],'plan'=>$p['id']]);$source=null;foreach(salaryCatalog()['sources'] as $s)if($s['id']===$p['id'])$source=$s;foreach($p['jobs'] as $job)save($t,'salary_jobs',['id'=>'SJ-'.$job['id'],'frame'=>$frame['id'],'name'=>$job['name'],'source'=>$p['id'],'source_hash'=>$source['sha256'],'groups'=>['ids'=>[$job['id']],'baseSequence'=>0],'base_from'=>'2026-05-01','law'=>$p['act'].' · Anexo II','workload'=>$job['hours']]);save($t,'rules',['id'=>'RULE-'.$p['id'],'plan'=>$p['id'],'sequence'=>1,'status'=>'Rascunho','config'=>['label'=>'Regra fictícia · '.$p['name'],'kind'=>'Capacitação','from'=>'2026-05-01','until'=>null,'months'=>24,'score'=>$p['family']==='legislativo'?75:70,'hours'=>$p['family']==='legislativo'?30:40,'maxAbsences'=>0,'stable'=>true,'basis'=>$p['act'],'notes'=>'Modelo demonstrativo; confira todos os artigos do plano e a análise de cada matrícula.'],'actor'=>'installer','created'=>date(DATE_ATOM)]);}
 $people=[];foreach($base['people'] as $p){$p['id']='LINK-'.$p['id'];$p['unitId']=$units[$p['unit']];$plan=null;foreach($base['plans'] as $x)if($x['id']===$p['planId'])$plan=$x;$job=null;foreach($plan['jobs'] as $x)if($x['id']===$p['jobId'])$job=$x;$index=null;foreach($job['cells'] as $i=>$cell)if((string)$cell['level']===(string)$p['level']&&(int)$cell['stage']===(int)$p['stage']&&$cell['band']===$p['band'])$index=$i;if($index===null)throw new Fault('A base contém enquadramento sem tabela.',500);$p['salary']=['jobId'=>'SJ-'.$job['id'],'groupId'=>$job['id'],'rowIndex'=>$index,'context'=>salaryContextKey($p),'target'=>null,'basis'=>$plan['act'].' · célula fictícia explicitamente vinculada','actor'=>'installer'];foreach($p['processes'] as &$proc){$target=null;foreach($job['cells'] as $i=>$cell)if((string)$cell['level']===(string)$proc['targetLevel']&&(int)$cell['stage']===(int)$proc['targetStage']&&$cell['band']===$p['band'])$target=$i;if($target!==null)$proc['salaryTarget']=array_replace($p['salary'],['rowIndex'=>$target,'target'=>j([$proc['id'],$proc['targetLevel'],$proc['targetStage'],$proc['type']]),'forecastDate'=>'2027-01-01']);}unset($proc);$p['evaluations']=array_reverse($p['evaluations']);$p['events']=array_reverse($p['events']);save($t,'links',$p);if(!isset($people[$p['personId']])||$p['admission']<$people[$p['personId']]['admission'])$people[$p['personId']]=$p;}
 foreach($base['functions'] as $f)save($t,'paid_functions',$f);
 $users=[];foreach(json_decode((string)file_get_contents(TR_PRIVATE.'/demo-accounts.json'),true) as $a){$id=uid();$unit=$a['unit']?$units[$a['unit']]:null;$cpfHash=isset($a['cpf'])?hash_hmac('sha256',cpf($a['cpf']),config()['key']):null;query('INSERT INTO tr_users(id,tenant,email,name,role,person,unit,power,password_hash,cpf_hash,active,is_demo,demo_until,must_change,auth_epoch) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$t,$a['email'],$a['name'],$a['role'],$a['person'],$unit,$a['power'],$a['password_hash'],$cpfHash,1,1,date('Y-m-d',strtotime('+30 days')),0,1]);$a['id']=$id;$users[]=$a;}
 $appointments=[];foreach($base['plans'] as $plan){$members=[];foreach($users as $u)if($u['role']==='commission'&&($people[$u['person']]['planId']??null)===$plan['id']){$p=$people[$u['person']];$members[]=['memberId'=>$u['id'],'linkId'=>$p['id'],'personId'=>$p['personId'],'name'=>$p['name'],'admission'=>$p['admission'],'representation'=>count($members)===0?'Administração':(count($members)===1?'Sindicato':'Assembleia'),'indication'=>'Indicação fictícia DEMO-C/2026'];}$unitIds=[];foreach($base['people'] as $p)if($p['planId']===$plan['id'])$unitIds[$units[$p['unit']]]=true;foreach(array_keys($unitIds) as $unit){$a=save($t,'appointments',['id'=>uid(),'plan'=>$plan['id'],'unit'=>$unit,'lotation'=>'','name'=>'Comissão '.$plan['name'].' · DEMONSTRAÇÃO','act'=>'Nomeação fictícia DEMO-C/2026','start'=>'2026-01-01','end'=>'2027-12-31','active'=>true,'members'=>$members]);$appointments[]=$a;}}
 // PDFs modelo ficam no cofre privado. Não são comprovantes reais de formação.
 $pdf=(string)file_get_contents(TR_RELEASE.'/data/certificado-modelo.pdf');foreach(records($t,'links') as $p){$a=null;foreach($appointments as $x)if($x['plan']===$p['planId']&&$x['unit']===$p['unitId'])$a=$x;if(!$a)continue;$valid=true;foreach($a['members'] as $m)if($m['personId']===$p['personId']||$m['admission']>=$p['admission'])$valid=false;if(!$valid)continue;$id=uid();file_put_contents(TR_PRIVATE.'/data/'.$id.'.enc',seal($pdf),LOCK_EX);@chmod(TR_PRIVATE.'/data/'.$id.'.enc',0600);query('INSERT INTO tr_files(id,tenant,link_id,name,size,hash,created) VALUES(?,?,?,?,?,?,?)',[$id,$t,$p['id'],'DEMO-documento-modelo.pdf',strlen($pdf),hash('sha256',$pdf),date(DATE_ATOM)]);save($t,'certificates',['id'=>$id,'link'=>$p['id'],'employee'=>$p['name'],'registration'=>$p['registration'],'plan'=>$p['planId'],'appointment'=>$a['id'],'name'=>'DEMO · Documento modelo para conferência','category'=>'Capacitação pertinente ao plano','categoryId'=>'demo-capacitacao','destination'=>'Progressão horizontal','kind'=>'Capacitação','targetLevel'=>'','hours'=>40,'completed'=>'2026-05-15','reviewers'=>$a['members'],'votes'=>[],'hash'=>hash('sha256',$pdf),'fileName'=>'DEMO-documento-modelo.pdf','size'=>strlen($pdf),'submittedBy'=>'installer','created'=>date(DATE_ATOM),'createdDay'=>today(),'demo'=>true]);}
 foreach($base['municipality']['contracts'] as $c){$x=['id'=>$c['id'],'number'=>$c['id'],'scope'=>$c['power'],'start'=>'2026-01-01','end'=>'2027-12-31','status'=>'Ativo'];query('INSERT INTO tr_contracts(id,tenant,payload) VALUES(?,?,?)',[$x['id'],$t,j($x)]);}audit($t,'demo.seed.complete','100 pessoas;110 matrículas;3 planos');
}
